xml.Script:
        include 'Figures\Scripts\Vectors.inc';

        Colors[ 0] := '8B0A50'; // DeepPink
        Colors[ 1] := '0000FF'; // Blue
        Colors[ 2] := '00BFFF'; // DeepSky
        Colors[ 3] := '007700'; // Green
        Colors[ 4] := 'FFFF00'; // Yellow
        Colors[ 5] := 'FF6000'; // Orange
        Colors[ 6] := 'FF0000'; // Red

        Colors[ 7] := 'FF5BBD'; // MediumPink
        Colors[ 8] := '44AA99'; // Teal
        Colors[ 9] := '00FFFF'; // Cyan
        Colors[10] := '00FF00'; // Lime
        Colors[11] := 'F0E68C'; // Khaki
        Colors[12] := 'FF7F50'; // Coral
        Colors[13] := 'CD5C5C'; // Indian

        clTop     := 'FFFFFF'; // White
        clBottom  := '333333'; // Black

        R1 := 0.5;
        N := 7;
        nAngle := 2*Pi / N;
        nAngle2 := nAngle / 2;

        H1 := R1 * sqrt((cos(nAngle2) - cos(nAngle)) / 2);

        A1 := VectorRotatingAngle(0, R1, H1, R1 * sin(nAngle), R1 *cos(nAngle), H1, R1 * sin(nAngle2), R1 * cos(nAngle2),-H1);  // (A[0], A[1], B[0])
        A2 := A1 * 2;
        A3 := A1 * 3;

        VectorRotatePoint(R1 * sin(nAngle), R1 *cos(nAngle), H1,  0, R1, H1, -A1, True);  // (A[1], A[0], -A1, True)
        H2 := Ans_Z;                                                                                                                  
        R2 := VectorLength(Ans_X, Ans_Y, 0);                                                                                          

        D := VectorDistanceToPlane(0, R1, H1, R1 * sin(nAngle), R1 * cos(nAngle), H1, 0);  // (A[0], A[1], 0)                     

        DCut := D * 0.85;

        for i := 0 to N - 1 do begin
            sa := sin(nAngle * i);
            ca := cos(nAngle * i);
            sa2 := sin(nAngle * (i + 1/2));
            ca2 := cos(nAngle * (i + 1/2));

            Ax[i] :=  R1 * sa;
            Ay[i] :=  R1 * ca;

            Bx[i] :=  R1 * sa2;
            By[i] :=  R1 * ca2;

            Cx[i] :=  R2 * sa2;
            Cy[i] :=  R2 * ca2;

            Dx[i] :=  R2 * sa;
            Dy[i] :=  R2 * ca;
        end;
        Az := H1;
        Bz :=-H1;
        Cz := H2;
        Dz :=-H2;

        function Next(i); // cycle in N-ring (0..6, 7..13 etc)
        begin
            Result := i + 1;
            if Result mod N = 0 then
                Result := Result - N;
        end;

Macro.Script:
c  := Next(c );
v1 := Next(v1);
v2 := Next(v2);
v3 := Next(v3);
v4 := Next(v4);
v5 := Next(v5);
